"""Generate deterministic synthetic telemetry so the tooling can be validated.

There is no vehicle hardware yet, which means there is no real log - and a parser
and a plot writer that have never seen a record prove nothing. This module
produces synthetic captures that are:

* **clearly labelled.** Every generated file begins with ``#`` comment lines
  naming the file as SYNTHETIC and saying in as many words that it is not
  measured data. A synthetic capture is a fixture for the tooling, never
  evidence about the vehicle, and it must never be quoted as such.
* **consistent with the schema.** Lines are written by a mirror of the firmware
  formatter, field for field and at the same resolution, so a synthetic file
  exercises the parser against the real wire format rather than against a
  convenient paraphrase.
* **internally consistent.** The event lane is derived from the sample lane with
  the same rule the firmware's own transition detector uses, so a nominal
  synthetic run has no phase-change mismatches; the variant that simulates a
  dropped burst is the one that does, on purpose, because that is a real
  condition the tooling has to report rather than hide.
* **reproducible.** Every value comes from a fixed seed and fixed arithmetic.
  Regenerating the samples produces identical bytes, so a report computed from
  them is reproducible too.

What the synthetic data deliberately does **not** contain: any measured physical
fact. The "position" is arithmetic over a velocity model, not a wheel's travel;
the "battery counts" are a decorative ramp, not an ADC reading; and the phase
timings are a fiction written by this file. Numbers like these must never reach
``VERIFIED_STATE.md``.
"""

from __future__ import annotations

import math
import os
import random
from dataclasses import dataclass
from typing import Optional, Sequence

from . import schema

__all__ = [
    "SYNTHETIC_MARKER",
    "SyntheticSpec",
    "SPECS",
    "generate_lines",
    "generate_text",
    "write_samples",
]

SYNTHETIC_MARKER = "SYNTHETIC"

# One header line per entry. Each is a single line on purpose: `generate_lines()`
# returns lines, and an entry containing an embedded newline would make the
# in-memory capture differ from the file it is written to.
_HEADER_LINES: tuple[str, ...] = (
    f"# {SYNTHETIC_MARKER} TELEMETRY - generated fixture, not measured data",
    "# NOT MEASURED DATA. Generated by tools/telemetry/evtelemetry/synthetic.py to "
    "validate the telemetry tooling.",
    "# Do not draw physical conclusions from it and never cite it in VERIFIED_STATE.md.",
)


# ---------------------------------------------------------------------------
# Spec
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class PhaseLeg:
    """One phase of the synthetic run and the velocity it demands."""

    phase: str
    duration_ms: int
    velocity_start_mps: float
    velocity_end_mps: float


@dataclass(frozen=True)
class SyntheticSpec:
    """Everything that decides a synthetic capture."""

    run_id: str
    seed: int
    cadence_ms: int = 20
    geometry_scale: float = 1.0
    # The forward target, in metres of the synthetic "believed" position.
    target_m: float = 6.0
    # A burst of omitted samples beginning at this tick index, and how many.
    drop_burst_start_index: int = -1
    drop_burst_count: int = 0
    # The tick index at which a fault latches, or -1 for none.
    fault_index: int = -1
    fault_code: str = "None"
    # Extra operator events to place before the run begins.
    extra_operator_events: tuple[tuple[str, str], ...] = ()

    @property
    def legs(self) -> tuple[PhaseLeg, ...]:
        """The phase timeline. Scaled lengths keep the legs self-consistent."""
        return (
            PhaseLeg("Idle", 200, 0.0, 0.0),
            PhaseLeg("ParameterValid", 120, 0.0, 0.0),
            PhaseLeg("Armed", 160, 0.0, 0.0),
            PhaseLeg("OptionalDelay", 1480, 0.0, 0.0),
            PhaseLeg("Approach", 7000, 0.0, 0.70),
            PhaseLeg("Capture", 700, 0.70, 0.55),
            PhaseLeg("Push", 3000, 0.55, 0.50),
            PhaseLeg("ForwardDecel", 1200, 0.50, 0.08),
            PhaseLeg("BrakeZeroSpeed", 400, 0.08, 0.0),
            PhaseLeg("Reverse", 5000, 0.0, -0.55),
            PhaseLeg("FinalApproach", 3000, -0.55, -0.10),
            PhaseLeg("FinalBrake", 600, -0.10, 0.0),
            PhaseLeg("Done", 400, 0.0, 0.0),
        )


# The fixtures the project ships. A (nominal), B (a different distance plus a
# dropped burst and a rejected command), C (a fault that ends the run).
SPECS: tuple[SyntheticSpec, ...] = (
    SyntheticSpec(run_id="SYNTHETIC-A", seed=20260927),
    SyntheticSpec(
        run_id="SYNTHETIC-B",
        seed=20260928,
        target_m=6.25,
        # The burst straddles the Push -> ForwardDecel tick (index 633), so the
        # sample lane loses the boundary the event lane still reports. That is
        # exactly the condition `phase_change_mismatch_count` exists to expose.
        drop_burst_start_index=631,
        drop_burst_count=6,
        extra_operator_events=(("CommandRejected", "RunUnderway"),),
    ),
    SyntheticSpec(
        run_id="SYNTHETIC-C",
        seed=20260929,
        fault_index=520,
        fault_code="PhaseTimeout",
    ),
)


# ---------------------------------------------------------------------------
# Formatting (a mirror of TelemetryFormat.h, so a synthetic line is a real line)
# ---------------------------------------------------------------------------

_MISSING = schema.MISSING_FIELD


def _fixed(value: Optional[float], decimals: int = schema.FIELD_DECIMALS) -> str:
    """The firmware's `appendFixed()`: integer rounding, fixed sentinels."""
    if value is None:
        return schema.SENTINEL_OVF
    if math.isnan(value):
        return schema.SENTINEL_NAN
    if math.isinf(value):
        return schema.SENTINEL_INF if value > 0 else schema.SENTINEL_NEG_INF
    if abs(value) >= 1.0e7:
        return schema.SENTINEL_OVF
    scale = 10 ** decimals
    scaled = math.floor(value * scale + 0.5)
    sign = "-" if scaled < 0 else ""
    scaled = abs(scaled)
    whole, fraction = divmod(scaled, scale)
    return f"{sign}{whole}.{fraction:0{decimals}d}"


def _sample_line(fields: dict[str, str]) -> str:
    parts = [schema.SAMPLE_PREFIX]
    for key in schema.SAMPLE_FIELDS:
        parts.append(f"{key}={fields[key]}")
    return ",".join(parts)


def _event_line(fields: dict[str, str]) -> str:
    parts = [schema.EVENT_PREFIX]
    for key in schema.EVENT_FIELDS:
        parts.append(f"{key}={fields[key]}")
    return ",".join(parts)


# ---------------------------------------------------------------------------
# Generation
# ---------------------------------------------------------------------------


@dataclass
class _Tick:
    index: int
    t_ms: int
    phase: str
    armed: bool
    position_m: float
    position_ok: bool
    velocity_mps: float
    velocity_ok: bool
    velocity_cmd_mps: float
    remaining_m: float
    motor: str
    effort_permille: int
    battery_counts: int
    current_counts: int
    nfault_low: bool
    fault: str
    authz: str
    check: str
    dropped: bool = False


def _demanded_velocity(spec: SyntheticSpec, index: int) -> tuple[str, float]:
    """The phase and demanded velocity at a tick index."""
    tick_ms = index * spec.cadence_ms
    elapsed = 0
    for leg in spec.legs:
        if tick_ms < elapsed + leg.duration_ms:
            fraction = (tick_ms - elapsed) / max(1, leg.duration_ms)
            velocity = leg.velocity_start_mps + (
                leg.velocity_end_mps - leg.velocity_start_mps
            ) * fraction
            return leg.phase, velocity
        elapsed += leg.duration_ms
    final = spec.legs[-1]
    return final.phase, final.velocity_end_mps


def _motor_for(phase: str, velocity_cmd_mps: float, armed: bool, fault: str) -> str:
    if fault != "None":
        return "Disabled"
    if not armed:
        return "Disabled"
    if phase in ("Done",):
        return "Coast"
    if phase in ("BrakeZeroSpeed", "FinalBrake"):
        return "Brake"
    if abs(velocity_cmd_mps) < 0.02:
        return "Brake" if phase not in ("Idle", "ParameterValid", "Armed", "OptionalDelay") else "Disabled"
    return "DriveForward" if velocity_cmd_mps > 0 else "DriveReverse"


def _effort_for(
    phase: str, motor: str, velocity_cmd_mps: float, velocity_mps: float, rng: random.Random
) -> int:
    if motor in ("Disabled", "Coast"):
        return 0
    if motor == "Brake":
        # A braking effort that falls away as the synthetic speed reaches zero.
        returning = max(0.0, abs(velocity_mps))
        return max(0, min(1000, int(round(120.0 + 600.0 * returning + rng.uniform(-20, 20)))))
    error = velocity_cmd_mps - velocity_mps
    effort = 260.0 + 900.0 * error + rng.uniform(-18.0, 18.0)
    return max(0, min(1000, int(round(effort))))


def _authz_for(armed: bool, fault: str, motor: str) -> str:
    if fault != "None":
        return "ForcedFaultStop"
    if not armed:
        return "DeniedNotArmed"
    if motor in ("Disabled", "Coast", "Brake"):
        return "AuthorizedStop"
    return "AuthorizedDrive"


def _build_ticks(spec: SyntheticSpec) -> list[_Tick]:
    rng = random.Random(spec.seed)
    ticks: list[_Tick] = []
    total_ms = sum(leg.duration_ms for leg in spec.legs)
    count = int(total_ms // spec.cadence_ms)

    position_m = 0.0
    velocity_mps = 0.0
    battery = 812.0

    for index in range(count):
        phase, velocity_cmd = _demanded_velocity(spec, index)
        t_ms = index * spec.cadence_ms

        # Arming happens at the end of the Armed phase's predecessor: the run is
        # armed for everything after the `Armed` phase begins.
        armed = phase not in ("Idle", "ParameterValid") and index * spec.cadence_ms >= _arm_time_ms(spec)

        fault = spec.fault_code if (spec.fault_index >= 0 and index >= spec.fault_index) else "None"
        if fault != "None":
            phase = "Fault"
            velocity_cmd = 0.0

        # First-order lag toward the demand, plus a little deterministic noise:
        # the measured velocity therefore tracks the command without equalling
        # it, which is what gives the tracking-error metric something to show.
        velocity_mps += (velocity_cmd - velocity_mps) * (spec.cadence_ms / 120.0)
        velocity_mps += rng.uniform(-0.008, 0.008)
        if velocity_cmd == 0.0 and abs(velocity_mps) < 0.01:
            velocity_mps = 0.0

        position_m += velocity_mps * (spec.cadence_ms / 1000.0)

        motor = _motor_for(phase, velocity_cmd, armed, fault)
        effort = _effort_for(phase, motor, velocity_cmd, velocity_mps, rng)

        battery -= 0.03 + rng.uniform(0.0, 0.01)
        current = 180.0 if motor in ("Disabled", "Coast") else 505.0
        current += abs(velocity_mps) * 40.0 + rng.uniform(-6.0, 6.0)

        # The estimator is not usable for the first few ticks of a session.
        ready = index >= 3

        dropped = (
            spec.drop_burst_count > 0
            and spec.drop_burst_start_index >= 0
            and spec.drop_burst_start_index <= index < spec.drop_burst_start_index + spec.drop_burst_count
        )

        ticks.append(
            _Tick(
                index=index,
                t_ms=t_ms,
                phase=phase,
                armed=armed,
                position_m=position_m,
                position_ok=ready,
                velocity_mps=velocity_mps,
                velocity_ok=ready,
                velocity_cmd_mps=velocity_cmd,
                remaining_m=spec.target_m - position_m,
                motor=motor,
                effort_permille=effort,
                battery_counts=max(0, min(65535, int(round(battery)))),
                current_counts=max(0, min(65535, int(round(current)))),
                nfault_low=False,
                fault=fault,
                authz=_authz_for(armed, fault, motor),
                check="none",
                dropped=dropped,
            )
        )

    return ticks


def _arm_time_ms(spec: SyntheticSpec) -> int:
    elapsed = 0
    for leg in spec.legs:
        if leg.phase == "Armed":
            return elapsed
        elapsed += leg.duration_ms
    return 0


def _events_from_ticks(
    ticks: Sequence[_Tick],
) -> dict[int, list[tuple[str, str, str, bool, str]]]:
    """The transitions, per tick, by the firmware's own detector rule.

    Order is fixed: a newly latched fault, then an arming change, then a phase
    change - the same order `TelemetryEventDetector::observe()` reports.
    """
    by_tick: dict[int, list[tuple[str, str, str, bool, str]]] = {}
    previous_phase: Optional[str] = None
    previous_armed: Optional[bool] = None
    previous_fault: Optional[str] = None

    for tick in ticks:
        batch: list[tuple[str, str, str, bool, str]] = []
        if previous_fault is not None and tick.fault != previous_fault and tick.fault != "None":
            batch.append(("FaultLatched", tick.fault, tick.phase, tick.armed, tick.fault))
        if previous_armed is not None and tick.armed != previous_armed:
            batch.append(
                (
                    "Armed" if tick.armed else "Disarmed",
                    _MISSING,
                    tick.phase,
                    tick.armed,
                    tick.fault,
                )
            )
        if previous_phase is not None and tick.phase != previous_phase:
            batch.append(("PhaseChange", tick.phase, tick.phase, tick.armed, tick.fault))
        if batch:
            by_tick[tick.index] = batch
        previous_phase = tick.phase
        previous_armed = tick.armed
        previous_fault = tick.fault

    return by_tick


def _operator_events(spec: SyntheticSpec) -> list[tuple[int, str, str, str, bool, str]]:
    """The pre-run operator traffic, before the first sample."""
    events: list[tuple[int, str, str, str, bool, str]] = [
        (0, "Boot", _MISSING, "Idle", False, "None"),
        (0, "TelemetryEnabled", _MISSING, "Idle", False, "None"),
        (40, "ChainReset", _MISSING, "Idle", False, "None"),
        (60, "ConfigSet", _MISSING, "Idle", False, "None"),
        (80, "ConfigSet", _MISSING, "Idle", False, "None"),
        (150, "AnnounceAccepted", _MISSING, "ParameterValid", False, "None"),
    ]
    for offset, (code, detail) in enumerate(spec.extra_operator_events):
        events.append((200 + offset * 20, code, detail, "ParameterValid", False, "None"))
    return events


def generate_lines(spec: SyntheticSpec) -> list[str]:
    """The complete synthetic capture, as the lines a serial port would deliver."""
    ticks = _build_ticks(spec)
    transitions = _events_from_ticks(ticks)

    lines: list[str] = [
        *_HEADER_LINES,
        f"# run_id: {spec.run_id}",
        f"# schema: {schema.SAMPLE_PREFIX}/{schema.EVENT_PREFIX} version {schema.SCHEMA_VERSION}",
        f"# generator seed: {spec.seed}; control cadence: {spec.cadence_ms} ms",
    ]

    drop_samples = 0
    drop_events = 0

    def event_line(t_ms: int, code: str, detail: str, phase: str, armed: bool, fault: str) -> str:
        return _event_line(
            {
                "ver": str(schema.SCHEMA_VERSION),
                "t_ms": str(t_ms),
                "phase": phase,
                "armed": "1" if armed else "0",
                "event": code,
                "detail": detail,
                "fault": fault,
                "drop_s": str(drop_samples),
                "drop_e": str(drop_events),
            }
        )

    for t_ms, code, detail, phase, armed, fault in _operator_events(spec):
        lines.append(event_line(t_ms, code, detail, phase, armed, fault))

    for tick in ticks:
        for code, detail, phase, armed, fault in transitions.get(tick.index, []):
            lines.append(event_line(tick.t_ms, code, detail, phase, armed, fault))

        if tick.dropped:
            # A record the queue could not store: it never reaches the wire, and
            # the counter goes up for everything stored after it.
            drop_samples += 1
            continue

        lines.append(
            _sample_line(
                {
                    "ver": str(schema.SCHEMA_VERSION),
                    "t_ms": str(tick.t_ms),
                    "dt_ms": str(spec.cadence_ms),
                    "phase": tick.phase,
                    "cmd": _command_for(tick),
                    "armed": "1" if tick.armed else "0",
                    "pos_m": _fixed(tick.position_m),
                    "pos_ok": "1" if tick.position_ok else "0",
                    "vel_mps": _fixed(tick.velocity_mps),
                    "vel_ok": "1" if tick.velocity_ok else "0",
                    "vel_cmd_mps": _fixed(tick.velocity_cmd_mps),
                    "rem_m": _fixed(tick.remaining_m),
                    "motor": tick.motor,
                    "effort_permille": str(tick.effort_permille),
                    "batt_counts": str(tick.battery_counts),
                    "curr_counts": str(tick.current_counts),
                    "nfault_low": "1" if tick.nfault_low else "0",
                    "fault": tick.fault,
                    "authz": tick.authz,
                    "check": tick.check,
                    "drop_s": str(drop_samples),
                    "drop_e": str(drop_events),
                }
            )
        )

    return lines


def _command_for(tick: _Tick) -> str:
    if tick.motor == "DriveForward":
        return "DriveForward"
    if tick.motor == "DriveReverse":
        return "DriveReverse"
    if tick.motor == "Brake":
        return "BrakeForward" if tick.velocity_cmd_mps >= 0 else "BrakeReverse"
    if tick.motor == "Coast":
        return "RampDownForward" if tick.velocity_cmd_mps >= 0 else "RampDownReverse"
    return "none"


def generate_text(spec: SyntheticSpec) -> str:
    return "\n".join(generate_lines(spec)) + "\n"


def write_samples(out_dir: str, *, force: bool = False) -> list[str]:
    """Writes every shipped synthetic fixture. Returns the paths written."""
    os.makedirs(out_dir, exist_ok=True)
    written: list[str] = []
    for spec in SPECS:
        path = os.path.join(out_dir, f"{spec.run_id.lower().replace('-', '_')}.csv")
        text = generate_text(spec)
        if os.path.exists(path) and not force:
            with open(path, "r", encoding="utf-8") as handle:
                if handle.read() == text:
                    written.append(path)
                    continue
        with open(path, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
        written.append(path)
    return written
